<input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="staff_id" value="<?= e((string)($values['staff_id']??'')) ?>">
<?php if(in_array($action,['create','edit'],true)): ?><div class="staff-account-fields"><label>Staff name *<input name="name" autocomplete="name" maxlength="120" required value="<?= e($values['name']??'') ?>"></label><label>Login email *<input name="email" type="email" autocomplete="username" maxlength="190" required value="<?= e($values['email']??'') ?>"></label></div><?php endif; ?>
<?php if(in_array($action,['create','reset'],true)): ?><div class="staff-account-fields"><label><?= $action==='reset'?'New password':'Password' ?> *<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><label>Confirm password *<input name="password_confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label></div><p class="subtle-text">Use at least 12 characters (maximum 72 bytes). Share the credentials with the staff member directly. Passwords cannot be viewed later.</p><?php endif; ?>
<?php if($action==='create'): ?><p class="subtle-text">The account will be active with no permissions. Grant the access it needs after creating it.</p><?php elseif($action==='edit'): ?><p class="subtle-text">Changing the login email signs out existing sessions. The password and permissions stay the same.</p><?php elseif($action==='reset'): ?><label class="staff-confirm"><input type="checkbox" name="confirmed" value="1" required> Reset this password and sign out all existing sessions.</label><?php else: ?><input type="hidden" name="active" value="<?= $statusTarget ?>"><p data-staff-status-description><?= $statusTarget==='0'?'This staff member will be signed out and unable to log in. Their records and permissions will be retained.':'This staff member will be able to sign in with their current credentials and saved permissions.' ?></p><label class="staff-confirm"><input type="checkbox" name="confirmed" value="1" required> I confirm this account status change.</label><?php endif; ?>
<p class="alert staff-form-error" role="alert" <?= empty($error)?'hidden':'' ?>><?= e($error??'') ?></p>
<footer class="staff-dialog-footer"><?php if(!empty($inDialog)): ?><button type="button" class="button" data-staff-close>Cancel</button><?php else: ?><a class="button" href="<?= e(url('/staff')) ?>">Cancel</a><?php endif; ?><button type="submit" class="button button-primary"><?= $action==='create'?'Create staff':($action==='reset'?'Reset password':($action==='status'?'Confirm change':'Save changes')) ?></button></footer>
